            ld (fn_s3d_render_w_vb), a		; S3d.cls 249
            ld b, 6		; S3d.cls 250
fn_s3d_render_cp_nm:		; S3d.cls 251
            ld a, (fn_s3d_render_w_va)		; S3d.cls 252
