            ld (fn_s3d_render_w_vb), a		; S3d.cls 265
            djnz fn_s3d_render_cp_nm		; S3d.cls 266
            ret                     ; (both 0: looking straight up or down) [267]
fn_s3d_render_cp_go:		; S3d.cls 268
            ld a, (fn_s3d_render_w_va)		; S3d.cls 269
            sra a		; S3d.cls 270
            sra a		; S3d.cls 271
            sra a		; S3d.cls 272
            ld (fn_s3d_render_w_va), a            ; dx [273]
            ld a, (fn_s3d_render_w_vb)		; S3d.cls 274
