            sra a		; S3d.cls 291
            ld c, a		; S3d.cls 292
            ld a, (fn_s3d_render_w_va)		; S3d.cls 293
            sra a		; S3d.cls 294
            ld b, a		; S3d.cls 295
            push bc		; S3d.cls 296
            sub c		; S3d.cls 297
            call fn_s3d_render_cp_x		; S3d.cls 298
            ld (gfx_x0), hl		; S3d.cls 299
            pop bc		; S3d.cls 300
            push bc		; S3d.cls 301
            ld a, c		; S3d.cls 302
            add a, b		; S3d.cls 303
            neg		; S3d.cls 304
            call fn_s3d_render_cp_y		; S3d.cls 305
            ld (gfx_y0), hl		; S3d.cls 306
            call fn_s3d_render_cp_tip		; S3d.cls 307
            call gfx_line		; S3d.cls 308
            pop bc		; S3d.cls 309
            ld a, b		; S3d.cls 310
            add a, c		; S3d.cls 311
            call fn_s3d_render_cp_x		; S3d.cls 312
