            ld (gfx_y1), hl		; S3d.cls 328
            ret		; S3d.cls 329
; cp_x / cp_y - HL = 296 / 182 + A (signed)
fn_s3d_render_cp_x:		; S3d.cls 331
            ld hl, 296		; S3d.cls 332
            jr fn_s3d_render_cp_add		; S3d.cls 333
fn_s3d_render_cp_y:		; S3d.cls 334
