            inc ix		; S3d.cls 695
            inc ix		; S3d.cls 696
            ld de, 6		; S3d.cls 697
            add iy, de		; S3d.cls 698
            pop bc		; S3d.cls 699
            djnz fn_s3d_render_t3_lp		; S3d.cls 700
            ret		; S3d.cls 701
; tb_one - DE = the basis number: 256 entries from IX (6 bytes apart)
fn_s3d_render_tb_one:		; S3d.cls 703
