            ld h, d		; S3d.cls 705
            sra h		; S3d.cls 706
            rr l		; S3d.cls 707
            sra h		; S3d.cls 708
            rr l		; S3d.cls 709
            sra h		; S3d.cls 710
            rr l		; S3d.cls 711
            sra h		; S3d.cls 712
            rr l		; S3d.cls 713
            ld (fn_s3d_render_w_v), hl		; S3d.cls 714
