            ld (fn_s3d_render_w_acc), hl		; S3d.cls 724
            ld a, e		; S3d.cls 725
            ld (fn_s3d_render_w_acc + 2), a		; S3d.cls 726
            ld a, 128		; S3d.cls 727
            call fn_s3d_render_tb_run		; S3d.cls 728
