            ld b, a		; S3d.cls 760
            push de		; S3d.cls 761
            ld de, 6		; S3d.cls 762
            add ix, de		; S3d.cls 763
            pop de		; S3d.cls 764
            ld a, (fn_s3d_render_w_cnt)		; S3d.cls 765
            dec a		; S3d.cls 766
            ld (fn_s3d_render_w_cnt), a		; S3d.cls 767
