; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_turbo_on:	jp 5
kw_turbo_off:	jp 7
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_goto_ifzero_n:	jp 15
kw_forupv_n:	jp 25
kw_next1l_n:	jp 31
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_inc:		jp 51
kw_dec:		jp 52
kw_add:		jp 53
kw_addl:		jp 54
kw_subvv:	jp 55
kw_2x:		jp 57
kw_mulvl:	jp 61
kw_divvv:	jp 63
kw_divvl:	jp 64
kw_divlv:	jp 65
kw_modvv:	jp 66
kw_modvl:	jp 67
kw_negv:		jp 69
kw_andvv:	jp 72
kw_andvl:	jp 73
kw_orvv:		jp 74
kw_notv:		jp 78
kw_scpltvv:	jp 79
kw_scpltvl:	jp 80
kw_scplevl:	jp 82
kw_scpgtvv:	jp 83
kw_scpgtvl:	jp 84
kw_scpgevl:	jp 86
kw_cpeqvl:	jp 96
kw_cpnevl:	jp 98
kw_vtovptr8:	jp 104
kw_aget:		jp 111
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_cls:		jp 147
kw_locatell:	jp 148
kw_model:	jp 150
kw_ticks:	jp 154
kw_strleft:	jp 156
kw_strchr:	jp 174
kw_strstr:	jp 176
kw_strhex:	jp 177
kw_strspace:	jp 178
kw_sget:		jp 194
kw_sset:		jp 195
kw_l_mov:	jp 206
kw_l_itol:	jp 207
kw_l_add:	jp 209
kw_l_mul:	jp 228
mem_go:		jp 245
mem_readbyte:	jp 254
mem_readword:	jp 255
mem_sel:		jp 258
mem_pages:	jp 259
mem_freepages:	jp 260
